140	        }
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        ownerDto.setBulkSignupWarning(isBulkSignupWarningActive());
143	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
144	    }
