146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
149	        validateRequiredOwnerFields(ownerFieldsDto);
150	        LocalDate suppliedOrDefaultDate =
151	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
152	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
153	        rejectDailyLimitExceeded(registrationDate);
154	        rejectCityAtCapacity(ownerFieldsDto.getCity());
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        owner.setAddress(normalizeAddress(owner.getAddress()));
158	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
159	        owner.setTelephone(normalizedTelephone);
160	        rejectDuplicateTelephone(normalizedTelephone);
161	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
162	        owner.setEmail(normalizeEmail(owner.getEmail()));
163	        owner.setRegistrationDate(registrationDate);
164	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
165	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
166	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
