269	
270	    /**
271	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
272	     * offending field is collected so the caller learns exactly which values must be supplied.
273	     *
274	     * @param ownerFieldsDto the submitted owner payload
275	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
276	     *         telephone is missing or blank
277	     */
278	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
279	        List<String> missingFields = new ArrayList<>();
280	        if (isBlank(ownerFieldsDto.getFirstName())) {
281	            missingFields.add("firstName");
282	        }
283	        if (isBlank(ownerFieldsDto.getLastName())) {
284	            missingFields.add("lastName");
285	        }
286	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
287	            missingFields.add("address");
288	        }
289	        if (isBlank(ownerFieldsDto.getCity())) {
290	            missingFields.add("city");
291	        }
292	        if (isBlank(ownerFieldsDto.getTelephone())) {
293	            missingFields.add("telephone");
294	        }
295	        if (!missingFields.isEmpty()) {
296	            throw new MissingOwnerFieldsException(missingFields);
297	        }
298	    }
299	
300	    private boolean isBlank(String value) {
301	        return value == null || value.isBlank();
302	    }
303	
304	    /**
305	     * Counts the existing owners who, before this create, already share the given first and last name.
306	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
307	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
308	     * case or spacing still count as the same name.
309	     *
310	     * @param firstName the first name of the owner being created
311	     * @param lastName the last name of the owner being created
312	     * @return the number of existing owners sharing both names (zero when none)
313	     */
314	    private int countNamesakes(String firstName, String lastName) {
315	        String first = normalizeHouseholdField(firstName);
316	        String last = normalizeHouseholdField(lastName);
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
319	                && normalizeHouseholdField(existing.getLastName()).equals(last))
320	            .count();
321	    }
322	
323	    /**
324	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
325	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
326	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
327	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
328	     * more owners the create is rejected as a conflict.
329	     *
330	     * @param city the city of the owner being created
331	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
332	     */
333	    /**
334	     * Rejects an owner create once the maximum number of owners have already been registered on the
335	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
336	     * which is always a business day (a weekend effective date is rolled forward to the following
337	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
338	     * business day the create is rejected as too many requests. Because a weekend effective date is
339	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
340	     *
341	     * @param businessDay the adjusted business day the owner being created would be registered on
342	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
343	     */
344	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
345	        long ownersOnDay = this.clinicService.findAllOwners().stream()
346	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
347	            .count();
348	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
349	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
350	        }
351	    }
352	
353	    /**
354	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
355	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
356	     * was supplied on the request or defaulted to the server's current date.
357	     *
358	     * @param date the effective registration date (supplied or defaulted)
359	     * @return the same date when it is a weekday, otherwise the following Monday
360	     */
361	    /**
362	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
363	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
364	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
365	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
366	     *
367	     * @return {@code true} when more than the threshold number of owners are already registered on
368	     *         today's business day, otherwise {@code false}
369	     */
370	    private boolean isBulkSignupWarningActive() {
371	        LocalDate today = toBusinessDay(LocalDate.now());
372	        long ownersToday = this.clinicService.findAllOwners().stream()
373	            .filter(existing -> today.equals(existing.getRegistrationDate()))
374	            .count();
375	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
376	    }
377	
378	    private LocalDate toBusinessDay(LocalDate date) {
379	        return switch (date.getDayOfWeek()) {
380	            case SATURDAY -> date.plusDays(2);
381	            case SUNDAY -> date.plusDays(1);
382	            default -> date;
383	        };
384	    }
385	
386	    private void rejectCityAtCapacity(String city) {
387	        String normalizedCity = normalizeHouseholdField(city);
388	        long ownersInCity = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
390	            .count();
391	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
392	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
393	        }
394	    }
395	
396	    /**
397	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
398	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
399	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
400	     * of owners already in that city (e.g. 'SYD-SMI-0007').
401	     *
402	     * @param city the owner's city
403	     * @param lastName the owner's last name
404	     * @return the formatted customer code
405	     */
406	    private String generateCustomerCode(String city, String lastName) {
407	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
408	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
409	        String normalizedCity = normalizeHouseholdField(city);
410	        int sequence = (int) this.clinicService.findAllOwners().stream()
411	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
412	            .count() + 1;
413	        return String.format("%s-%s-%04d", city3, last3, sequence);
414	    }
415	
416	    /**
417	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
418	     * customerCode is the owner's customer code and YY is the last two digits of the
419	     * registrationDate year (e.g. 'SMI-0007-M26').
420	     *
421	     * @param customerCode the owner's customer code
422	     * @param registrationDate the owner's registration date
423	     * @return the formatted membership number
424	     */
425	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
426	        String yy = String.format("%02d", registrationDate.getYear() % 100);
427	        return customerCode + "-M" + yy;
428	    }
429	
430	    /**
431	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
432	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
433	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
434	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
435	     * stored and returned.
436	     *
437	     * @param telephone the raw telephone value from the request
438	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
439	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
440	     */
441	    private String normalizeTelephone(String telephone) {
442	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
443	        String e164;
444	        if (cleaned.startsWith("+")) {
445	            e164 = cleaned;
446	        } else {
447	            String national = cleaned;
448	            if (national.startsWith("0")) {
449	                national = national.substring(1);
450	            }
451	            e164 = "+61" + national;
452	        }
453	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
454	            throw new InvalidOwnerFieldsException(List.of("telephone"));
455	        }
456	        return e164;
457	    }
458	
459	    /**
460	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
461	     * left unset. When a value is present it must be a syntactically valid address; the normalized
462	     * form stored and returned is the value lower-cased.
463	     *
464	     * @param email the raw email value from the request, or {@code null} when none was supplied
465	     * @return the lower-cased email, or {@code null} when no email was supplied
466	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
467	     */
468	    private String normalizeEmail(String email) {
469	        if (email == null || email.isBlank()) {
470	            return null;
471	        }
472	        if (!EMAIL_PATTERN.matcher(email).matches()) {
473	            throw new InvalidOwnerFieldsException(List.of("email"));
474	        }
475	        return email.toLowerCase(Locale.ROOT);
476	    }
477	
478	    /**
479	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
480	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
481	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
482	     * normalized form is what gets stored, returned and used for every address comparison (the
483	     * required-field check, household duplicate detection and the shared household id).
484	     *
485	     * @param address the raw address value from the request, or {@code null}
486	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
487	     */
488	    private String normalizeAddress(String address) {
489	        if (address == null) {
490	            return "";
491	        }
492	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
493	        if (collapsed.isEmpty()) {
494	            return "";
495	        }
496	        String[] tokens = collapsed.split(" ");
497	        for (int i = 0; i < tokens.length; i++) {
498	            switch (tokens[i]) {
499	                case "ST" -> tokens[i] = "STREET";
500	                case "RD" -> tokens[i] = "ROAD";
501	                case "AVE" -> tokens[i] = "AVENUE";
502	                default -> { }
503	            }
504	        }
505	        return String.join(" ", tokens);
506	    }
507	
508	    /**
509	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
510	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
511	     * directly and is therefore independent of the punctuation a caller supplied.
512	     *
513	     * @param e164Telephone the E.164 telephone of the owner being created
514	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
515	     */
516	    private void rejectDuplicateTelephone(String e164Telephone) {
517	        boolean inUse = this.clinicService.findAllOwners().stream()
518	            .map(Owner::getTelephone)
519	            .filter(existing -> existing != null)
520	            .anyMatch(e164Telephone::equals);
521	        if (inUse) {
522	            throw new DuplicateOwnerTelephoneException(e164Telephone);
523	        }
524	    }
525	
526	    /**
527	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
528	     * last name and a normalized address: last names are compared case-insensitively after whitespace
529	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
530	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
531	     * abbreviation still count as the same household.
532	     * <p>
533	     * When the owner's last name and address already belong to at least one other owner the behaviour
534	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
535	     * household. If it is true the create is allowed and every member of the household - the existing
536	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
537	     * read. When no other owner shares the last name and address no identifier is assigned.
538	     *
539	     * @param owner the owner being created
540	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
541	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
542	     *         address and {@code sharesHousehold} is not true
543	     */
544	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
545	        String lastName = normalizeHouseholdField(owner.getLastName());
546	        String address = normalizeAddress(owner.getAddress());
547	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
548	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
549	                && normalizeAddress(existing.getAddress()).equals(address))
550	            .toList();
551	        if (housemates.isEmpty()) {
552	            return;
553	        }
554	        if (!Boolean.TRUE.equals(sharesHousehold)) {
555	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
556	        }
557	        String householdId = generateHouseholdId(lastName, address);
558	        owner.setHouseholdId(householdId);
559	        for (Owner housemate : housemates) {
560	            if (!householdId.equals(housemate.getHouseholdId())) {
561	                housemate.setHouseholdId(householdId);
562	                this.clinicService.saveOwner(housemate);
563	            }
564	        }
565	    }
566	
567	    /**
568	     * Builds the stable identifier shared by the members of one household. It is derived purely from
569	     * the normalized last name and address, so every owner of a given household deterministically
570	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
571	     * two normalized fields joined by a single space.
572	     *
573	     * @param normalizedLastName the household's last name, already normalized for comparison
574	     * @param normalizedAddress the household's address, already normalized for comparison
575	     * @return the shared household identifier
576	     */
577	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
578	        String key = normalizedLastName + '�' + normalizedAddress;
579	        try {
580	            byte[] digest = MessageDigest.getInstance("SHA-256")
581	                .digest(key.getBytes(StandardCharsets.UTF_8));
582	            StringBuilder hex = new StringBuilder();
583	            for (byte b : digest) {
584	                hex.append(String.format("%02X", b));
585	                if (hex.length() >= 12) {
586	                    break;
587	                }
588	            }
589	            return hex.substring(0, 12);
590	        } catch (NoSuchAlgorithmException e) {
591	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
592	        }
593	    }
594	
595	    /**
596	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
597	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
598	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
599	     * expands common abbreviations.
600	     *
601	     * @param value the raw last name, or {@code null}
602	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
603	     */
604	    private String normalizeHouseholdField(String value) {
605	        if (value == null) {
606	            return "";
607	        }
608	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
609	    }
610	}
